def is_multi_node(args: argparse.Namespace) -> bool:
    return bool(getattr(args, "worker_hosts", None))


class _ClusterScope:
    """Placeholder boundary for multi-node delegation.

    The packaged verifier does not silently invent an SSH launcher. Callers
    should start the cluster with vllm-ascend-serving/serve_start.py and use
    ``--verify-mode http`` against its already-started head URL.
    """

    def __init__(self, args: argparse.Namespace, launch_kwargs: dict):
        self.args = args
        self.launch_kwargs = launch_kwargs

    def __enter__(self):
        raise RuntimeError(
            "multi-node routing replay requires serve_start.py to launch the cluster; "
            "run this verifier with --verify-mode http against the already-started head API"
        )

    def __exit__(self, exc_type, exc, tb):
        return False


def cluster_scope(args: argparse.Namespace, launch_kwargs: dict) -> _ClusterScope:
    return _ClusterScope(args, launch_kwargs)


# ---------------------------------------------------------------------------
# Baseline command parsing
# ---------------------------------------------------------------------------

# Value-taking flags (need the following token as their value).
_VALUE_FLAGS = {
    "--tensor-parallel-size",
    "-tp",
    "--data-parallel-size",
    "-dp",
    "--pipeline-parallel-size",
    "-pp",
    "--max-model-len",
    "--block-size",
    "--port",
    "-p",
    "--host",
    "--served-model-name",
    "--served_model_name",
    "--compilation-config",
    "--weight-transfer-config",
    "--additional-config",
}


def split_flags(command: str) -> list[str]:
    """Split a `vllm serve ...` command string into a list of tokens.

    Handles shell-quoted values (single quotes) so JSON configs like
    --compilation-config '{"cudagraph_mode": "..."}' are preserved intact.
    """
    lexer = shlex.shlex(command, posix=True)
    lexer.whitespace_split = True
    lexer.commenters = ""
    return list(lexer)


def parse_baseline(command: str) -> dict:
    """Parse the baseline `vllm serve` command into a normalized dict.

    Recognized keys: model, served_model_name, tensor_parallel_size,
    data_parallel_size, pipeline_parallel_size, enable_expert_parallel,
    graph_mode, port, host, extra (all other tokens preserved for step-1
    http relaunch).
    """
    tokens = split_flags(command)

    parsed = {
        "model": None,
        "served_model_name": "auto",
        "tensor_parallel_size": 1,
        "data_parallel_size": 1,
        "pipeline_parallel_size": 1,
        "enable_expert_parallel": False,
        "graph_mode": None,
        "port": 8000,
        "host": "127.0.0.1",
        "extra": [],
    }

    i = 0
    while i < len(tokens):
        tok = tokens[i]

        if tok in ("vllm", "serve"):
            i += 1
            continue

        # The model path is the first bare token (positional arg of `vllm serve`).
        if parsed["model"] is None and tok.startswith("--") is False and tok.startswith("-") is False:
            parsed["model"] = tok
            i += 1
            continue

        if tok in ("--tensor-parallel-size", "-tp"):
            parsed["tensor_parallel_size"] = int(tokens[i + 1])
            i += 2
            continue
        if tok in ("--data-parallel-size", "-dp"):
            parsed["data_parallel_size"] = int(tokens[i + 1])
            i += 2
            continue
        if tok in ("--pipeline-parallel-size", "-pp"):
            parsed["pipeline_parallel_size"] = int(tokens[i + 1])
            i += 2
            continue
        if tok in ("--served-model-name", "--served_model_name"):
            parsed["served_model_name"] = tokens[i + 1]
            i += 2
            continue
        if tok in ("--enable-expert-parallel", "--enable_expert_parallel"):
            parsed["enable_expert_parallel"] = True
            i += 1
            continue
        if tok in ("--compilation-config",):
            parsed["graph_mode"] = tokens[i + 1]
            parsed["extra"].extend([tok, tokens[i + 1]])
            i += 2
            continue
        if tok in ("--port", "-p"):
            parsed["port"] = int(tokens[i + 1])
            i += 2
            continue
        if tok == "--host":
            parsed["host"] = tokens[i + 1]
            i += 2
            continue

        if tok in _VALUE_FLAGS:
            # Unknown value-taking flag: keep it and its value verbatim.
            parsed["extra"].extend([tok, tokens[i + 1]])
            i += 2
            continue

        parsed["extra"].append(tok)
        i += 1

    if parsed["model"] is None:
        raise ValueError(
            "Could not find a model path in the baseline command. "
            "Expected a `vllm serve <model> ...` command."
        )
    parsed["extra"] = [t for t in parsed["extra"] if t not in ("vllm", "serve")]
    return parsed


# ---------------------------------------------------------------------------
# routed_experts validation (shared core, from feature-matrix.md + e2e test)
# ---------------------------------------------------------------------------



def infer_expert_shape(model: str) -> tuple[int|None, int|None, int|None]:
    """Infer routed-experts shape dimensions from model config.json."""
    path = Path(model)
    if not path.is_dir():
        raise ValueError(f"model path must be a local directory to infer expert shape: {model}")
    config_path = path / "config.json"
    if not config_path.exists():
        raise ValueError(f"model config not found: {config_path}")
    config = json.loads(config_path.read_text(encoding="utf-8"))
    layers = config.get("num_hidden_layers") or config.get("num_layers")
    experts_per_token = (config.get("num_experts_per_tok") or config.get("num_selected_experts")
                         or config.get("top_k") or config.get("moe_top_k"))
    if layers is None or experts_per_token is None:
        raise ValueError("config.json lacks num_hidden_layers/num_layers or num_experts_per_tok/top_k")
    return (None, int(layers), int(experts_per_token))

def validate_routed_experts_array(re_array: np.ndarray, expected_shape: tuple[int|None, int|None, int|None] | None = None) -> None:
    """Validate a decoded routed_experts numpy array.

    Mirrors `assert_valid_routed_experts` from the upstream e2e / test
    `test_routed_experts.py`:
      * ndim == 3, shape (num_tokens, num_layers, num_experts_per_tok)
      * num_tokens > 0
      * all values valid expert ids (>= 0)
    """
    assert re_array is not None, "routed_experts is null/empty"
    assert getattr(re_array, "ndim", 0) == 3, f"expected 3-dim routed_experts, got {re_array.ndim}"
    num_tokens, num_layers, num_experts_per_tok = re_array.shape
    assert num_tokens > 0, f"routed_experts has no tokens: shape {re_array.shape}"
    assert num_experts_per_tok > 0, f"routed_experts has no experts-per-tok: shape {re_array.shape}"
    if expected_shape:
        for actual, expected, name in zip(re_array.shape, expected_shape, ("tokens", "layers", "experts_per_tok")):
            if expected is not None:
                assert actual == expected, f"unexpected routed_experts {name}: got {actual}, expected {expected}; shape={re_array.shape}"
    assert re_array.min() >= 0, f"routed_experts contains negative expert ids: min={re_array.min()}"
    print(
        f"[OK] routed_experts valid: shape={re_array.shape}, "
        f"min={int(re_array.min())}, max={int(re_array.max())}, "
        f"unique={len(np.unique(re_array))}"
    )


def validate_output_text(text: str) -> None:
    """Validate the generated text has no garble/replacement chars (AI 判定)."""
    assert text and len(text.strip()) > 0, "generated output text is empty"
    bad = ("\ufffd",)  # U+FFFD replacement character => decode/garble issue
    for ch in bad:
        assert ch not in text, f"generated output contains replacement char {ch!r} (garble)"
    print(f"[OK] output text ok (len={len(text)}): {text[:80]!r}")


# ---------------------------------------------------------------------------
# Step 1: HTTP mode (baseline command launched as `vllm serve` HTTP server)
# ---------------------------------------------------------------------------


def build_http_command(baseline: dict, feature_args: list[str], port: int) -> list[str]:
    """Rebuild the `vllm serve` command, adding the routing-replay feature.

    Preserves the baseline topology (TP/DP/EP/graph-mode/port derived from the
    baseline command) and appends `--enable-return-routed-experts`.
    """
    cmd = ["vllm", "serve"]
    cmd.append(baseline["model"])
    # Keep the HTTP request model name aligned with the service name.  The
    # previous implementation parsed --served-model-name as an opaque extra
    # flag and then hard-coded model=auto in the request, which returned 404
    # whenever the service exposed a name such as "policy".
    if baseline.get("served_model_name"):
        cmd += ["--served-model-name", str(baseline["served_model_name"])]
    cmd.extend(baseline["extra"])
    # Re-emit the parallel topology (TP/DP/PP/EP) that parse_baseline extracted
    # out of the baseline command into the parsed dict.  Without this the http
    # relaunch runs at TP=1/DP=1 and OOMs on multi-card baselines.
    if baseline["tensor_parallel_size"] != 1:
        cmd += ["--tensor-parallel-size", str(baseline["tensor_parallel_size"])]
    if baseline["data_parallel_size"] != 1:
        cmd += ["--data-parallel-size", str(baseline["data_parallel_size"])]
    if baseline["pipeline_parallel_size"] != 1:
        cmd += ["--pipeline-parallel-size", str(baseline["pipeline_parallel_size"])]
    if baseline["enable_expert_parallel"]:
        cmd += ["--enable-expert-parallel"]
    cmd.extend(feature_args)
    # Ensure the routing replays switch is present.
    if "--enable-return-routed-experts" not in cmd:
        cmd.append("--enable-return-routed-experts")
    # Force the port we connect to.
    for i, tok in enumerate(cmd):
        if tok in ("--port", "-p"):
            cmd[i + 1] = str(port)
            break
    else:
        cmd.extend(["--port", str(port)])
    return cmd


def wait_http_ready(host: str, port: int, timeout: float = 600.0, proc: subprocess.Popen | None = None) -> None:
    health = f"http://{host}:{port}/health"
    start = time.time()
    last_log = 0.0
    while time.time() - start < timeout:
        try:
            r = requests.get(health, timeout=5)
            if r.status_code == 200:
                print(f"[OK] HTTP service ready: {health}")
                return
        except requests.RequestException:
            pass

        # If the spawned process exited unexpectedly, report it.
        if proc is not None and proc.poll() is not None:
            raise RuntimeError(
                f"vllm serve exited unexpectedly with code {proc.returncode} while waiting for {health}"
                f"\n--- stdout tail ---\n{_tail(proc)}\n--- stderr tail ---\n{_tail(proc, err=True)}"
            )

        now = time.time()
        if now - last_log >= 30:
            print(f"[WAIT] {health} not ready after {now - start:.0f}s ...")
            last_log = now
        time.sleep(5)

    raise TimeoutError(f"Timed out waiting for HTTP service ready at {health}")


_STDOUT_LOG: list[str] = []


def _read_proc_output(proc, err=False) -> list[str]:
    if err:
        return proc.stderr.read().splitlines() if proc.stderr else []
    return proc.stdout.read().splitlines() if proc.stdout else []


def _tail(proc, err: bool = False, n: int = 30) -> str:
    lines = _read_proc_output(proc, err=err)
    return "\n".join(lines[-n:])


def verify_http(baseline: dict, port: int, host: str, feature_args: list[str],
                cluster_args: argparse.Namespace | None = None, expected_shape=None) -> None:
    """Step 1: launch only the routed-experts feature service and validate routed_experts. Baseline output is supplied externally when comparison is required.

    Single-node: launches ``vllm serve`` as a local subprocess (original path).
    Multi-node (cluster_args with --worker-hosts): delegates the cluster launch
    to ``serve_start.py`` (reused) and validates against the head node URL.
    """
    if cluster_args is not None and is_multi_node(cluster_args):
        launch_kwargs = dict(
            model=baseline["model"],
            tp=baseline["tensor_parallel_size"],
            dp=baseline["data_parallel_size"],
            extra_args=feature_args + [t for t in baseline["extra"] if t not in ("vllm", "serve")],
            port=port,
        )
        with cluster_scope(cluster_args, launch_kwargs) as url:
            if url is None:
                raise RuntimeError("multi-node launch produced no URL")
            _verify_http_routed_experts(
                url.rstrip("/") + "/v1/completions",
                expected_shape,
                model_name=baseline.get("served_model_name", "auto"),
            )
        return

    cmd = build_http_command(baseline, feature_args, port)
    print("[STEP 1 / http] launching baseline command:", " ".join(cmd))

    # The skill insists requests go through unproxied localhost; unset proxies.
    env = os.environ.copy()
    for key in ("http_proxy", "https_proxy", "HTTP_PROXY", "HTTPS_PROXY", "all_proxy", "ALL_PROXY"):
        env.pop(key, None)

    log_path = Path(f"router_replay_http_{port}.log")
    with open(log_path, "w", encoding="utf-8") as logf:
        proc = subprocess.Popen(
            cmd,
            env=env,
            stdout=logf,
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )

    try:
        wait_http_ready(host, port, proc=proc)
        _verify_http_routed_experts(
            f"http://{host}:{port}/v1/completions",
            expected_shape,
            model_name=baseline.get("served_model_name", "auto"),
        )
    finally:
        proc.terminate()
        try:
            proc.wait(timeout=60)
        except subprocess.TimeoutExpired:
            proc.kill()
        print(f"[STEP 1 / http] service stopped; log written to {log_path}")


def _verify_http_routed_experts(url: str, expected_shape=None, *, model_name: str = "auto") -> None:
    """POST a completion to *url* and validate text + routed_experts."""
    payload = {"model": model_name, "prompt": "San Francisco is a", "max_tokens": 32, "temperature": 0}
    resp = requests.post(url, json=payload, headers={"Content-Type": "application/json"}, timeout=600)
    assert resp.status_code == 200, f"HTTP completions failed: {resp.status_code} {resp.text[:500]}"
    data = resp.json()
    choice = data["choices"][0]
    text = choice.get("text", "")
    validate_output_text(text)

    re_b64 = choice.get("routed_experts")
    assert re_b64 is not None, (
        "routed_experts is null in the HTTP response. "
        "Is --enable-return-routed-experts active and is the model a MoE model?"
    )
    re_array = np.load(io.BytesIO(base64.b64decode(re_b64)))
    validate_routed_experts_array(re_array, expected_shape)
    chat_payload = {"model": model_name, "messages": [{"role": "user", "content": "San Francisco is a"}], "max_tokens": 32, "temperature": 0}
    chat_resp = requests.post(url.replace("/v1/completions", "/v1/chat/completions"), json=chat_payload, headers={"Content-Type": "application/json"}, timeout=600)
    assert chat_resp.status_code == 200, f"HTTP chat completions failed: {chat_resp.status_code} {chat_resp.text[:500]}"
    chat_choice = chat_resp.json()["choices"][0]
    validate_output_text((chat_choice.get("message") or {}).get("content", ""))
    chat_b64 = chat_choice.get("routed_experts")
    assert chat_b64 is not None, "routed_experts is missing from /v1/chat/completions response"
    chat_array = np.load(io.BytesIO(base64.b64decode(chat_b64)))
    validate_routed_experts_array(chat_array, expected_shape)
    print(f"[STEP 1 / http] PASS (completions shape={tuple(re_array.shape)}, chat shape={tuple(chat_array.shape)})")


# ---------------------------------------------------------------------------
# Step 2: inproc mode (in-process VllmRunner, matches upstream e2e test)
# ---------------------------------------------------------------------------


def verify_inproc(baseline: dict) -> None:
    """Step 2: in-process VllmRunner; read routed_experts tensor directly.

    Mirrors the upstream e2e test_moe_routing_replay.py using the parallel
    topology parsed from the baseline command.
    """
    print("[STEP 2 / inproc] building in-process VllmRunner from baseline params")

    # vLLM's offline ``LLM`` API deliberately rejects data_parallel_size > 1 in a
    # single process (see vllm/entrypoints/llm.py ``LLM(data_parallel_size=N) is
    # not supported for single-process usage`` unless
    # distributed_executor_backend == "external_launcher", which is a multi-process
    # launch, not in-proc).  For a DP>1 baseline we do NOT skip; instead we fold DP
    # into TP as an equivalent single-process approximation (DP -> 1, TP = DP*TP),
    # keeping the same total parallel degree, and print a clear notice.
    eff_tp = baseline["tensor_parallel_size"]
    eff_dp = baseline["data_parallel_size"]
    orig_dp = baseline["data_parallel_size"]
    if baseline.get("data_parallel_size", 1) > 1:
        eff_tp = baseline["tensor_parallel_size"] * baseline["data_parallel_size"]
        eff_dp = 1
        print(
            "[STEP 2 / inproc] NOTE: offline LLM() cannot run data_parallel_size>1 in a "
            f"single process (baseline DP={orig_dp}). Folding DP into TP as an equivalent "
            f"single-process approximation: DP {orig_dp}->1, TP {baseline['tensor_parallel_size']}"
            f"->{eff_tp}. (Total parallel degree preserved; HTTP step remains authoritative.)"
        )

    # Deferred imports: these pull in the vllm/vllm-ascend stack and must only
    # run on the actual NPU host (not on the skill authoring machine).
    from vllm import LLM, SamplingParams
    from vllm.sampling_params import RequestOutputKind

    llm_kwargs = dict(
        model=baseline["model"],
        tensor_parallel_size=eff_tp,
        data_parallel_size=eff_dp,
        pipeline_parallel_size=baseline["pipeline_parallel_size"],
        enable_expert_parallel=baseline["enable_expert_parallel"],
        enable_return_routed_experts=True,
        distributed_executor_backend="mp",
        # The baseline may carry a graph-mode >= eager setting; pass it through
        # verbatim if provided, otherwise use the skill's default.
        compilation_config=(
            json.loads(baseline["graph_mode"]) if baseline["graph_mode"] else {"cudagraph_mode": "FULL_DECODE_ONLY"}
        ),
        max_model_len=1024,
        block_size=16,
        enable_chunked_prefill=True,
    )
    print("[STEP 2 / inproc] LLM kwargs:", json.dumps(llm_kwargs, default=str))

    sampling_params = SamplingParams(
        max_tokens=5,
        temperature=0.8,
        top_p=0.95,
        output_kind=RequestOutputKind.FINAL_ONLY,
    )

    llm = LLM(**llm_kwargs)
    try:
        prompts = ["Hello, please introduce yourself."]
        outputs = llm.generate(prompts, sampling_params)
        out = outputs[0].outputs[0]
        assert out.finished, "generation did not finish"
        assert len(out.text) > 0, "output text is empty"
        validate_output_text(out.text)
        re_tensor = out.routed_experts
        assert re_tensor is not None, "routed_experts is None in inproc output"
        # vLLM versions return either a torch Tensor or a NumPy ndarray here.
        # Tensor.size() is callable, while ndarray.size is an integer property;
        # calling the latter caused: 'int' object is not callable.
        if hasattr(re_tensor, "detach"):
            re_array = re_tensor.detach().cpu().numpy()
        else:
            re_array = np.asarray(re_tensor)
        assert re_array.size > 0, "routed_experts has zero size"
        validate_routed_experts_array(re_array)
        print("[STEP 2 / inproc] PASS")
    finally:
        llm.llm_engine.engine_core.shutdown()
        del llm


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = create_feature_parser("Routing replay RL use-case verification (baseline-aware)")
    parser.add_argument(
        "--baseline-cmd",
        required=True,
        help="The baseline `vllm serve ...` command (model + TP/DP/EP/graph mode) generated by the skill.",
    )
    parser.add_argument("--baseline-result", default=None, help="Optional saved baseline JSON for output comparison")
    parser.add_argument("--expected-expert-layers", type=int, default=None, help="Expected routed_experts layer dimension")
    parser.add_argument("--expected-experts-per-token", type=int, default=None, help="Expected selected experts per token")
    parser.add_argument(
        "--verify-mode",
        dest="verification_mode",
        choices=["http", "inproc", "both"],
        default="both",
        help="Verification mode; 'both' runs http then inproc (default). "
        "Multi-node (--worker-hosts) runs HTTP only, since in-process LLM cannot span nodes.",
    )
    add_cluster_connection_arguments(parser)
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)

    baseline = parse_baseline(args.baseline_cmd)
    print("[baseline] parsed:", json.dumps(baseline, default=str))

    port = args.port or baseline["port"]
    host = args.host or baseline["host"]
    multi = is_multi_node(args)

    feature_args = ["--enable-return-routed-experts"]
    config_shape = infer_expert_shape(baseline["model"])
    expected_shape = (None, args.expected_expert_layers or config_shape[1], args.expected_experts_per_token or config_shape[2])
    print(f"[config] expected routed_experts shape dimensions: layers={expected_shape[1]}, experts_per_token={expected_shape[2]}")

    failures = []
    # Multi-node: http is the only applicable step (in-proc LLM is single-machine).
    if args.verification_mode in ("http", "both"):
        try:
            verify_http(baseline, port, host, feature_args, cluster_args=args if multi else None, expected_shape=expected_shape)
        except Exception as e:  # noqa: BLE001 - report & continue to inproc
            failures.append(("http", str(e)))
            print(f"[STEP 1 / http] FAILED: {e}", file=sys.stderr)

    if multi:
        if failures:
            print("\n=== Routing replay verification FAILED (multi-node, http only) ===", file=sys.stderr)
            for mode, err in failures:
                print(f"  [{mode}] {err}", file=sys.stderr)
            return 1
        print("\n=== Routing replay verification PASSED (multi-node http) ===")
        return 0

    if args.verification_mode in ("inproc", "both"):
        try:
            verify_inproc(baseline)
        except Exception as e:  # noqa: BLE001
            failures.append(("inproc", str(e)))
            print(f"[STEP 2 / inproc] FAILED: {e}", file=sys.stderr)

    if failures:
        print("\n=== Routing replay verification FAILED ===", file=sys.stderr)
        for mode, err in failures:
            print(f"  [{mode}] {err}", file=sys.stderr)
        return 1

    print("\n=== Routing replay verification PASSED (http + inproc) ===")
    return 0


if __name__ == "__main__":
    sys.exit(main())
